def pick(xs: list[int], seed: int) -> int:
    """Return an element of the non-empty list xs, chosen from seed.

    The same (xs, seed) pair always returns the same element. The
    function uses no randomness, so the result depends only on its
    inputs. Every returned value is an element of xs.
    """
    return xs[seed % len(xs)]


def test_pick_single_element_always_returned() -> None:
    for seed in (-7, 0, 1, 42, 10**9):
        assert pick([5], seed) == 5


def test_pick_is_deterministic_for_same_seed() -> None:
    xs = [3, 1, 4, 1, 5, 9, 2, 6]
    for seed in range(20):
        assert pick(xs, seed) == pick(xs, seed)


def test_pick_returns_member_of_list() -> None:
    xs = [10, 20, 30, 40]
    for seed in range(50):
        assert pick(xs, seed) in xs


def test_pick_repeated_calls_agree_across_fresh_copies() -> None:
    xs = [7, 8, 9]
    first = [pick(list(xs), s) for s in range(10)]
    second = [pick(list(xs), s) for s in range(10)]
    assert first == second
